import html,json,csv
from pathlib import Path

def render(report):
 e=html.escape;sections=[]
 for p in report['corridors']:
  if p['status']=='reference_missing':sections.append('<section class="panel"><h2>'+e(p['id'])+'</h2><p>Taux manquant : aucun calcul ni classement.</p></section>');continue
  r=p['reference'];tables=[]
  for comparison in p['comparisons']:
   rows=[]
   for row in comparison['ranked']:
    c=row['calculation'];rows.append('<tr><td>'+str(row['rank'])+'</td><td>'+e(row['label'])+'</td><td>'+e(c['principal'])+'</td><td>'+e(c['sender_fixed'])+' + '+e(c['sender_variable'])+'</td><td>'+e(c['effective_rate'])+'</td><td><strong>'+e(c['received'])+'</strong></td><td>'+e(c['reference_gap_percent'][:9])+' %</td></tr><tr><td colspan="7"><details><summary>Examiner le calcul</summary><pre>'+e(json.dumps(c,indent=2))+'</pre></details></td></tr>')
   errors=''.join('<p>'+e(x['label'])+' : '+e(x['reason'])+'</p>' for x in comparison['infeasible'])
   tables.append('<article class="comparison" data-corridor="'+e(p['id'],quote=True)+'" data-budget="'+e(comparison['budget'],quote=True)+'"><h3>Budget total : '+e(comparison['budget'])+' '+e(p['source'])+'</h3><div class="table"><table><thead><tr><th>Rang</th><th>Profil fictif</th><th>Principal</th><th>Frais source</th><th>Taux appliqué</th><th>Reçu ('+e(p['target'])+')</th><th>Écart relatif</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div>'+errors+'</article>')
  label='Taux fictif : aucun cours actuel représenté.' if r['data_kind']=='synthetic' else ('Taux de référence ancien : revue nécessaire avant utilisation.' if p['reference_stale'] else 'Taux de référence daté, pas une offre de transfert.')
  sections.append('<section class="panel corridor" data-corridor="'+e(p['id'],quote=True)+'"><h2>'+e(p['source'])+' → '+e(p['target'])+'</h2><p class="notice">'+label+'</p><p>Référence : '+e(r['rate'])+' · date '+e(r['date'])+' · '+e(r['provider'])+'</p>'+''.join(tables)+'</section>')
 options=''.join('<option value="'+e(p['id'],quote=True)+'">'+e(p['source'])+' → '+e(p['target'])+'</option>' for p in report['corridors'])
 budgets=sorted({c['budget'] for p in report['corridors'] for c in p['comparisons']},key=float)
 boptions=''.join('<option value="'+e(b,quote=True)+'">'+e(b)+'</option>' for b in budgets)
 return '''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Transfer Cost Observatory | Junior BOOTO Waba</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6f6;color:#15384a;font:16px/1.6 system-ui}main{max-width:1200px;margin:auto;padding:36px 24px}header{background:#173e4c;color:white;padding:36px;border-radius:22px}.eyebrow{color:#ade5d6;font-size:13px;letter-spacing:.12em}h1{font-size:clamp(32px,5vw,52px);line-height:1.1}.stats{display:flex;gap:18px;flex-wrap:wrap;margin:22px 0}.stat,.panel,.controls{background:white;padding:24px;border-radius:14px;border:1px solid #dce5e4;margin:16px 0}.stat{flex:1;min-width:170px}.stat b{font-size:32px;display:block}.notice{background:#fff1ce;padding:16px;border-radius:10px}.controls{display:flex;gap:24px;flex-wrap:wrap}select{font:inherit;display:block;padding:10px;border:1px solid #94aeb9;border-radius:7px;margin-top:5px}.table{overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:12px;text-align:left;border-bottom:1px solid #dce5e4;font-size:14px}summary{cursor:pointer;color:#14685d}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;background:#edf5f2;padding:18px}footer{color:#536d7c;padding:25px 0}[hidden]{display:none!important}@media(max-width:650px){main{padding:20px 14px}header{padding:24px}.controls>*{width:100%}}</style></head><body><main><header><span class="eyebrow">JUNIOR BOOTO WABA · PYTHON / DONNÉES</span><h1>Comprendre ce qui arrive<br>après les frais.</h1><p>Transfer Cost Observatory · comparaison à budget total égal</p></header>'''+f'<div class="stats"><div class="stat"><b>{report["summary"]["corridors"]}</b>corridors</div><div class="stat"><b>{report["summary"]["calculated_quotes"]}</b>calculs vérifiables</div><div class="stat"><b>A / B / C</b>profils fictifs</div></div><p class="notice"><strong>Simulation pédagogique.</strong> Aucune offre bancaire réelle, aucun partenariat, aucun transfert. Le classement compare seulement les profils du même corridor et du même budget.</p><p>Date d’évaluation de l’âge des références : {e(report["as_of"])}</p><div class="controls"><label>Corridor<select id="corridor"><option value="all">Tous</option>{options}</select></label><label>Budget source<select id="budget"><option value="all">Tous</option>{boptions}</select></label></div><p id="count" role="status" aria-live="polite"></p>'+''.join(sections)+'''<section class="panel"><h2>Le calcul explicable</h2><p>Le budget inclut le principal et les frais à l’envoi. Le pourcentage de frais porte sur le principal. La marge de change réduit le taux de référence ; les frais à réception sont en devise cible.</p><p>Principal = arrondi inférieur((budget − frais fixes) / (1 + pourcentage)).</p><p>Reçu = arrondi(principal × taux référence × (1 − marge) − frais réception).</p><p>L’écart au scénario sans frais est décomposé en frais source, budget non dépensé, marge de change, frais réception et arrondi. Ce n’est pas une marge commerciale observée.</p></section><footer><p>Calculs Python avec Decimal. Les filtres du navigateur sélectionnent les résultats sans recalcul flottant. Modifier les hypothèses JSON et relancer Python pour explorer d’autres budgets.</p><p>Connecteur Frankfurter v2 fourni ; l’appel tenté dans cette livraison a reçu HTTP 403. La démonstration utilise exclusivement des taux et tarifs fictifs. Taxes, frais intermédiaires, délais et plafonds non modélisés.</p><p lang="en">Explainable Python transfer-cost simulation with fixed total budgets and explicit reference-rate provenance. Synthetic tariff profiles, no banking integration.</p></footer></main><script>function filter(){let n=0;const c=document.getElementById('corridor').value,b=document.getElementById('budget').value;document.querySelectorAll('.comparison').forEach(x=>{x.hidden=!((c==='all'||x.dataset.corridor===c)&&(b==='all'||x.dataset.budget===b));if(!x.hidden)n++;});document.querySelectorAll('.corridor').forEach(x=>x.hidden=c!=='all'&&x.dataset.corridor!==c);document.getElementById('count').textContent=n+' comparaisons affichées';}['corridor','budget'].forEach(id=>document.getElementById(id).addEventListener('change',filter));filter();</script></body></html>'''

def export(report,directory):
 out=Path(directory);out.mkdir(parents=True,exist_ok=True)
 (out/'comparison.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8');(out/'dashboard.html').write_text(render(report),encoding='utf-8')
 fields=['corridor','source','target','budget','profile','rank','received','reference_gap_percent','rate_kind','rate_date']
 with (out/'comparison.csv').open('w',encoding='utf-8-sig',newline='') as stream:
  writer=csv.DictWriter(stream,fieldnames=fields);writer.writeheader()
  for p in report['corridors']:
   for c in p['comparisons']:
    for r in c['ranked']:writer.writerow({'corridor':p['id'],'source':p['source'],'target':p['target'],'budget':c['budget'],'profile':r['profile'],'rank':r['rank'],'received':r['calculation']['received'],'reference_gap_percent':r['calculation']['reference_gap_percent'],'rate_kind':p['reference']['data_kind'],'rate_date':p['reference']['date']})
